import {useLocation} from '@reach/router'
import {PageConfig, useNotificationsContext} from 'jaen'
import {navigate, PageProps} from 'gatsby'
import {useEffect, useMemo, useState} from 'react'
import {useIntl} from 'react-intl'

import {New} from '../../../components/cms/Pages/New'
import {
  CMSManagement,
  useCMSManagement
} from '../../../connectors/cms-management'
import {intlText} from '../../../lib/intl'

const PagesNew: React.FC = () => {
  const intl = useIntl()
  const {toast} = useNotificationsContext()
  const manager = useCMSManagement()

  const parentPages = useMemo(() => {
    const pages = manager.pages()

    const _parentPages: {
      [pageId: string]: {
        label: string
        templates: {
          [templateId: string]: {
            label: string
          }
        }
      }
    } = {}

    for (const page of pages) {
      const pageTemplates = manager.templatesForPage(page.id)

      if (pageTemplates.length > 0) {
        _parentPages[page.id] = {
          label: page.jaenPageMetadata.title || page.slug,
          templates: pageTemplates.reduce(
            (acc, template) => {
              acc[template.id] = {
                label: template.label
              }

              return acc
            },
            {} as {[key: string]: {label: string}}
          )
        }
      }
    }

    return _parentPages
  }, [])

  const location = useLocation()

  const [defaultParentPageId, setDefaultParentPageId] = useState<
    string | undefined
  >(undefined)

  const [addedPageId, setAddedPageId] = useState<string | undefined>(undefined)

  useEffect(() => {
    if (addedPageId) {
      navigate(manager.pagePath(addedPageId), {
        replace: true
      })

      setAddedPageId(undefined)
    }
  }, [addedPageId, manager.pagePath])

  useEffect(() => {
    try {
      const pageId = atob(location.hash.replace('#', ''))

      window.scrollTo(0, 0)

      if (parentPages[pageId]) {
        setDefaultParentPageId(pageId)
      }
    } catch (e) {
      console.error(e)
    }
  }, [location.hash, parentPages])

  return (
    <New
      form={{
        values: {
          parentPage: defaultParentPageId
        },
        parentPages,
        onSubmit: data => {
          const addedPageId = manager.addPage({
            slug: data.slug,
            template: data.template,
            parentPage: {
              id: data.parentPage
            },
            excludedFromIndex: data.isExcludedFromIndex,
            jaenPageMetadata: {
              title: data.title,
              image: data.image?.src,
              description: data.description,
              blogPost: data.blogPost
            }
          })

          toast({
            title: intl.formatMessage({
              id: 'CmsPagesNotificationsCreated',
              defaultMessage: 'Page created'
            }),
            description: intl.formatMessage(
              {
                id: 'CmsPagesNotificationsCreatedDescription',
                defaultMessage: 'Page {title} has been created'
              },
              {title: data.title}
            ),
            status: 'success'
          })

          setAddedPageId(addedPageId)
        }
      }}
    />
  )
}

const Page: React.FC<PageProps> = () => {
  return (
    <CMSManagement>
      <PagesNew />
    </CMSManagement>
  )
}

export default Page

export const pageConfig: PageConfig = {
  label: intlText('CmsPagesTableNewPage', 'New page'),
  breadcrumbs: [
    {
      label: intlText('CmsLabelsRoot', 'CMS'),
      path: '/cms/'
    },
    {
      label: intlText('CmsPagesBreadcrumbsPages', 'Pages'),
      path: '/cms/pages/'
    },
    {
      label: intlText('CmsPagesBreadcrumbsNew', 'New'),
      path: '/cms/pages/new/'
    }
  ],
  withoutJaenFrameStickyHeader: true,
  auth: {
    isAdminRequired: true
  },
  layout: {
    name: 'jaen',
    type: 'form'
  }
}

export {Head} from 'jaen'
